package com.crms.entity;import com.crms.enums.ApplicationStatus;import java.time.Instant;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.CompoundIndex;import org.springframework.data.mongodb.core.mapping.Document;@Document("applications") @CompoundIndex(name="student_job_unique",def="{'student._id':1,'job._id':1}",unique=true) public class Application{@Id private Long id;private Student student;private JobPosting job;private ApplicationStatus status=ApplicationStatus.PENDING;private Instant createdAt=Instant.now();public Long getId(){return id;}public void setId(Long v){id=v;}public Student getStudent(){return student;}public void setStudent(Student v){student=v;}public JobPosting getJob(){return job;}public void setJob(JobPosting v){job=v;}public ApplicationStatus getStatus(){return status;}public void setStatus(ApplicationStatus v){status=v;}public Instant getCreatedAt(){return createdAt;}}
